mapper.select:
SELECT ja.id, ja.job_id AS jobId, j.job_name AS jobName, j.enterprise_id AS enterpriseId, e.enterprise_name AS enterpriseName, ja.application_status AS applicationStatus, CASE ja.application_status WHEN 0 THEN '待处理' WHEN 1 THEN '已通过' WHEN 2 THEN '已拒绝' WHEN 3 THEN '已取消' ELSE '未知' END AS applicationStatusName, ja.application_time AS applicationTime FROM job_application ja LEFT JOIN job j ON j.id = ja.job_id LEFT JOIN enterprise e ON e.id = j.enterprise_id WHERE ja.student_id = #{param1}
AND ja.application_status = #{param2}
ORDER BY ja.application_time DESC
